CREATE TABLE `muscle_status` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `region_key` varchar(50) NOT NULL,
  `estimated_recovery` decimal(5,1) NOT NULL,
  `soreness` tinyint unsigned NOT NULL,
  `fatigue` tinyint unsigned NOT NULL,
  `strength` tinyint unsigned NOT NULL,
  `endurance` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_muscle` (`user_id`,`region_key`),
  CONSTRAINT `fk_muscle_status_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `muscle_status_chk_1` CHECK ((`estimated_recovery` >= 0)),
  CONSTRAINT `muscle_status_chk_2` CHECK ((`soreness` between 0 and 10)),
  CONSTRAINT `muscle_status_chk_3` CHECK ((`fatigue` between 0 and 10)),
  CONSTRAINT `muscle_status_chk_4` CHECK ((`strength` between 0 and 10)),
  CONSTRAINT `muscle_status_chk_5` CHECK ((`endurance` between 0 and 10))
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
