  `digestive_comfort` tinyint unsigned DEFAULT NULL,
  `food_tolerance` tinyint unsigned DEFAULT NULL,
  `abdominal_bloating` tinyint unsigned DEFAULT NULL,
  `abdominal_cramps` tinyint unsigned DEFAULT NULL,
  `nausea` tinyint unsigned DEFAULT NULL,
  PRIMARY KEY (`user_id`),
