  CONSTRAINT `small_intestine_chk_1` CHECK ((`digestive_comfort` between 0 and 10)),
  CONSTRAINT `small_intestine_chk_2` CHECK ((`food_tolerance` between 0 and 10)),
  CONSTRAINT `small_intestine_chk_3` CHECK ((`abdominal_bloating` between 0 and 10)),
  CONSTRAINT `small_intestine_chk_4` CHECK ((`abdominal_cramps` between 0 and 10)),
  CONSTRAINT `small_intestine_chk_5` CHECK ((`nausea` between 0 and 10))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
